/* ===== MINI-GAME: first-contact-hope (Steady the Flame) ===== */
const MG_FC={armed:false,active:false,t:0,flame:0.5,target:0.5,targetDrift:0,nomads:[],won:false,failed:false,failType:null,entryHold:0,exitHold:0,shownTip:false};
function mgFCInit(){MG_FC.armed=false;MG_FC.active=false;MG_FC.t=0;MG_FC.flame=0.5;MG_FC.target=0.5;MG_FC.targetDrift=0;MG_FC.nomads=[];MG_FC.won=false;MG_FC.failed=false;MG_FC.failType=null;MG_FC.entryHold=90;MG_FC.exitHold=0;MG_FC.shownTip=false;}
function mgFCArm(w){if(MG_FC.armed||MG_FC.active)return false;const grey=w.npcs.filter(x=>x.tribe===-1&&!x.burn).length;if(grey>=5||location.hash.includes('mg')){MG_FC.armed=true;return true;}return false;}
function mgFCTrigger(playerPos){if(!MG_FC.armed||MG_FC.active)return false;MG_FC.active=true;MG_FC.t=0;MG_FC.flame=0.5;MG_FC.target=0.5;MG_FC.targetDrift=0;MG_FC.nomads=[];for(let i=0;i<8;i++){const a=i*Math.PI/4;MG_FC.nomads.push({a:a,d:8+Math.random()*2,committed:0.5,recoil:0});}MG_FC.won=false;MG_FC.failed=false;MG_FC.failType=null;MG_FC.entryHold=90;MG_FC.exitHold=0;return true;}
function mgFCStep(clicked){if(MG_FC.entryHold>0){MG_FC.entryHold--;MG_FC.t++;return;}if(MG_FC.exitHold>0){MG_FC.exitHold--;MG_FC.t++;if(MG_FC.exitHold===0){MG_FC.active=false;MG_FC.armed=false;}return;}MG_FC.t++;if(clicked)MG_FC.flame=Math.min(1,MG_FC.flame+0.15);MG_FC.flame=Math.max(0,MG_FC.flame-0.006);MG_FC.targetDrift+=0.0008;MG_FC.target=0.5+0.08*Math.sin(MG_FC.targetDrift);const lo=MG_FC.target-0.12,hi=MG_FC.target+0.12;const steady=MG_FC.flame>=lo&&MG_FC.flame<=hi;const tooBright=MG_FC.flame>hi+0.15;const tooDim=MG_FC.flame<lo-0.15;let allClose=true,anyScattered=false;for(const n of MG_FC.nomads){if(steady){n.committed=Math.min(1,n.committed+0.015);n.recoil=Math.max(0,n.recoil-0.02);}else if(tooBright){n.committed=Math.max(0,n.committed-0.03);n.recoil=Math.min(1,n.recoil+0.05);}else if(tooDim){n.committed=Math.max(0,n.committed-0.02);n.recoil=0;}if(steady&&n.recoil<0.3)n.d=Math.max(1.2,n.d-0.04);else if(tooBright)n.d=Math.min(10,n.d+0.08);else if(tooDim)n.d=Math.min(10,n.d+0.03);if(n.d>2)allClose=false;if(n.d>8)anyScattered=true;}if(tooBright&&!MG_FC.failed){MG_FC.failed=true;MG_FC.failType='flare';MG_FC.exitHold=120;}if(tooDim&&!MG_FC.failed){MG_FC.failed=true;MG_FC.failType='dim';MG_FC.exitHold=120;}if(allClose&&!MG_FC.won&&!MG_FC.failed){MG_FC.won=true;MG_FC.exitHold=120;}}
function mgFCResolve(w){if(!MG_FC.won&&!MG_FC.failed)return null;if(MG_FC.won){let conv=0;for(const n of MG_FC.nomads)if(n.committed>0.7)conv++;for(let i=0;i<conv&&i<3;i++){const g=w.npcs.find(x=>x.tribe===-1&&!x.burn);if(g){g.v=w.player_pole*8;g.ever_nonzero=true;}}return 'convert_devout';}if(MG_FC.failed){if(MG_FC.failType==='flare'){let burn=0;for(const n of MG_FC.nomads)if(n.recoil>0.6)burn++;for(let i=0;i<burn&&i<2;i++){const g=w.npcs.find(x=>x.tribe===-1&&!x.burn);if(g){g.burn=true;g.v=0;}}return burn>0?'burnout':'no_effect';}else{let drift=0;for(const n of MG_FC.nomads)if(n.committed<0.3)drift++;return drift>3?'drift_apathy':'no_effect';}}return 'no_effect';}

