// M1: mgFCStep steady hold increases commitment
{mgFCInit();mgFCTrigger([10,10]);MG_FC.entryHold=0;MG_FC.flame=0.5;MG_FC.target=0.5;const c0=MG_FC.nomads[0].committed;for(let i=0;i<20;i++)mgFCStep(false);const c1=MG_FC.nomads[0].committed;out.push(['M1 steady flame increases nomad commitment',c1>c0,`${c0.toFixed(2)}->${c1.toFixed(2)}`]);}
// M2: mgFCStep flare triggers fail
{mgFCInit();mgFCTrigger([10,10]);MG_FC.entryHold=0;MG_FC.flame=0.95;for(let i=0;i<10;i++)mgFCStep(false);out.push(['M2 flare triggers fail',MG_FC.failed&&MG_FC.failType==='flare',`failed=${MG_FC.failed} type=${MG_FC.failType}`]);}
// M3: mgFCResolve win converts nomads
{const w=mk(7);mgFCInit();mgFCTrigger([10,10]);MG_FC.won=true;for(const n of MG_FC.nomads)n.committed=0.9;const g0=w.npcs.filter(x=>x.tribe===-1).length;const res=mgFCResolve(w);const g1=w.npcs.filter(x=>x.tribe===-1).length;out.push(['M3 win converts grey nomads',res==='convert_devout'&&g1<g0,`${g0}->${g1} res=${res}`]);}
